+
+UnmountOnlyAction::UnmountOnlyAction(const std::shared_ptr<StorageInfo> &storageInfo, const std::shared_ptr<StateInfo> &stateInfo, QObject *parent)
+    : ActionInterface(storageInfo, stateInfo, parent)
+    , m_hasStorageAccess(false)
+    , m_isRoot(false)
+    , m_isOpticalDisc(m_storageInfo->device().is<Solid::OpticalDisc>())
+{
+    if (m_storageInfo->device().is<Solid::StorageAccess>()) {
+        const Solid::StorageAccess *storageaccess = m_storageInfo->device().as<Solid::StorageAccess>();
+        if (storageaccess) {
+            m_hasStorageAccess = true;
+            m_isRoot = storageaccess->filePath() == u"/";
+        }
+    }
+
+    connect(m_stateInfo.get(), &StateInfo::stateChanged, this, &UnmountOnlyAction::updateIsValid);
+}
+
+UnmountOnlyAction::~UnmountOnlyAction() = default;
+
+QString UnmountOnlyAction::name() const
+{
+    return QStringLiteral("UnmountOnly");
+}
+
+QString UnmountOnlyAction::icon() const
+{
+    return QStringLiteral("media-eject");
+}
+
+QString UnmountOnlyAction::text() const
+{
+    return i18nc("@action:button unmount the device but keep it attached so it can be mounted again", "Unmount");
+}
+
+bool UnmountOnlyAction::isValid() const
+{
+    return m_hasStorageAccess && m_storageInfo->isRemovable() && !m_isRoot && !m_isOpticalDisc && m_stateInfo->isMounted();
+}
+
+void UnmountOnlyAction::triggered()
+{
+    Solid::Device device = m_storageInfo->device();
+    auto *access = device.as<Solid::StorageAccess>();
+    if (access && access->isAccessible()) {
+        access->unmount();
+    }
+}
+
+void UnmountOnlyAction::updateIsValid()
+{
+    Q_EMIT isValidChanged(name(), isValid());
+}
+
+#include "moc_unmountonlyaction.cpp"
